CREATE OR REPLACE FUNCTION public.ci_research_panel_release_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'complete' THEN
    RAISE EXCEPTION 'completed Civica Index research panel releases are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.ci_research_panel_rows_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.ci_research_panel_releases
    WHERE id = COALESCE(OLD.release_id, NEW.release_id) AND status = 'complete'
  ) THEN
    RAISE EXCEPTION 'completed Civica Index research panel rows are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_capture_research_evidence_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  before_row jsonb := to_jsonb(OLD);
  after_row jsonb := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(NEW) ELSE NULL END;
  evidence_id text;
  evidence_actor text;
  evidence_reason text;
BEGIN
  evidence_id := COALESCE(after_row->>'id', before_row->>'id', md5(before_row::text));
  evidence_actor := COALESCE(
    NULLIF(after_row->>'reviewer_id', ''),
    NULLIF(after_row->>'actor_id', ''),
    NULLIF(before_row->>'reviewer_id', ''),
    current_user
  );
  evidence_reason := COALESCE(
    NULLIF(after_row->>'status_reason', ''),
    NULLIF(after_row->>'review_notes', ''),
    NULLIF(after_row->>'disposition', ''),
    NULLIF(after_row->>'classification_reason', ''),
    NULLIF(before_row->>'status_reason', ''),
    lower(TG_OP) || '_retained_by_dat_016'
  );

  INSERT INTO research_evidence_history (
    entity_table, entity_id, operation, before, after, reason, actor_id
  ) VALUES (
    TG_TABLE_NAME, evidence_id, lower(TG_OP), before_row, after_row,
    evidence_reason, evidence_actor
  );

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_guard_candidate_release_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_candidates integer; actual_winners integer; linked_winners integer;
BEGIN
  IF TG_OP <> 'UPDATE' OR OLD.completeness_status <> 'staging' OR NEW.completeness_status <> 'complete_candidates'
     OR (to_jsonb(OLD) - 'completeness_status') IS DISTINCT FROM (to_jsonb(NEW) - 'completeness_status') THEN
    RAISE EXCEPTION 'candidate release % is immutable except staging finalization', OLD.vintage_label;
  END IF;
  SELECT count(*)::int, count(*) FILTER (WHERE is_canonical_at_cut)::int INTO actual_candidates, actual_winners
    FROM country_fact_vintage_candidates WHERE vintage_label=NEW.vintage_label;
  SELECT count(*)::int INTO linked_winners FROM country_fact_vintages v
    JOIN country_fact_vintage_candidates c ON c.id=v.canonical_candidate_id AND c.vintage_label=v.vintage_label AND c.is_canonical_at_cut
    WHERE v.vintage_label=NEW.vintage_label;
  IF actual_candidates <> NEW.candidate_count OR actual_winners <> NEW.winner_count OR linked_winners <> NEW.winner_count THEN
    RAISE EXCEPTION 'candidate release % is incomplete: candidates %/%, winners %/%, linked %/%', NEW.vintage_label,
      actual_candidates, NEW.candidate_count, actual_winners, NEW.winner_count, linked_winners, NEW.winner_count;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_candidate_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE release_status text;
BEGIN
  SELECT completeness_status INTO release_status FROM country_fact_vintage_releases
    WHERE vintage_label=COALESCE(OLD.vintage_label, NEW.vintage_label);
  IF release_status <> 'staging' THEN
    RAISE EXCEPTION 'frozen candidate vintage % is immutable', COALESCE(OLD.vintage_label, NEW.vintage_label);
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_reject_frozen_vintage_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'country_fact_vintages' OR OLD.vintage_label IS NOT NULL THEN
    RAISE EXCEPTION 'frozen vintage % is immutable; publish a new superseding version', OLD.vintage_label;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_validate_complete_candidate_winner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE release_status text; candidate_winner boolean;
BEGIN
  SELECT completeness_status INTO release_status FROM country_fact_vintage_releases WHERE vintage_label=NEW.vintage_label;
  IF release_status = 'complete_candidates' THEN
    IF NEW.canonical_candidate_id IS NULL THEN RAISE EXCEPTION 'complete candidate release requires canonical_candidate_id'; END IF;
    SELECT is_canonical_at_cut INTO candidate_winner FROM country_fact_vintage_candidates
      WHERE id=NEW.canonical_candidate_id AND vintage_label=NEW.vintage_label;
    IF candidate_winner IS DISTINCT FROM true THEN RAISE EXCEPTION 'canonical candidate pointer is not the frozen winner'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_validate_frozen_vintage_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parsed text[];
  published_period text;
  prior_label text;
BEGIN
  IF TG_TABLE_NAME = 'country_fact_vintages' THEN
    parsed := regexp_match(NEW.vintage_label, '^Civica Atlas Reconciled (v[^[:space:]]+) — vintage ([0-9]{4}-Q[1-4])$');
    IF parsed IS NULL OR NEW.methodology_version <> parsed[1] THEN
      RAISE EXCEPTION 'Atlas vintage label and methodology_version disagree';
    END IF;
    published_period := parsed[2];
    SELECT vintage_label INTO prior_label FROM country_fact_vintages
      WHERE vintage_label <> NEW.vintage_label
        AND vintage_label LIKE '%vintage ' || published_period LIMIT 1;
    IF prior_label IS NOT NULL AND NEW.supersedes_vintage_label IS NULL THEN
      RAISE EXCEPTION 'corrected Atlas vintage must name supersedes_vintage_label';
    END IF;
  ELSE
    IF NEW.vintage_label IS NULL THEN RETURN NEW; END IF;
    parsed := regexp_match(NEW.vintage_label, '^Civica Index ([0-9]{4}) Q([1-4]) \(([^)]+)\)$');
    IF parsed IS NULL OR NEW.quarter <> parsed[1] || '-Q' || parsed[2]
       OR lower(NEW.methodology_version) <> lower(parsed[3]) THEN
      RAISE EXCEPTION 'Civica Index vintage label, quarter, and methodology_version disagree';
    END IF;
    SELECT vintage_label INTO prior_label FROM ci_composite_scores
      WHERE quarter = NEW.quarter AND vintage_label IS NOT NULL
        AND vintage_label <> NEW.vintage_label LIMIT 1;
    IF prior_label IS NOT NULL AND NEW.supersedes_vintage_label IS NULL THEN
      RAISE EXCEPTION 'corrected Civica Index vintage must name supersedes_vintage_label';
    END IF;
  END IF;

  IF NEW.supersedes_vintage_label IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM (
      SELECT vintage_label FROM country_fact_vintages WHERE TG_TABLE_NAME = 'country_fact_vintages'
      UNION ALL
      SELECT vintage_label FROM ci_composite_scores WHERE TG_TABLE_NAME = 'ci_composite_scores'
    ) prior WHERE prior.vintage_label = NEW.supersedes_vintage_label
  ) THEN
    RAISE EXCEPTION 'supersedes_vintage_label does not identify an existing frozen vintage';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_validate_statement_subject()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  subject_exists boolean;
BEGIN
  CASE NEW.subject_table
    WHEN 'constitutions' THEN SELECT EXISTS(SELECT 1 FROM constitutions x WHERE x.id = NEW.subject_id) INTO subject_exists;
    WHEN 'elections' THEN SELECT EXISTS(SELECT 1 FROM elections x WHERE x.id = NEW.subject_id) INTO subject_exists;
    WHEN 'government_bodies' THEN SELECT EXISTS(SELECT 1 FROM government_bodies x WHERE x.id = NEW.subject_id) INTO subject_exists;
    WHEN 'jurisdictions' THEN SELECT EXISTS(SELECT 1 FROM jurisdictions x WHERE x.id = NEW.subject_id) INTO subject_exists;
    WHEN 'terms' THEN SELECT EXISTS(SELECT 1 FROM terms x WHERE x.id = NEW.subject_id) INTO subject_exists;
    ELSE RAISE EXCEPTION 'Unsupported statement subject table: %', NEW.subject_table;
  END CASE;
  IF NOT subject_exists THEN
    RAISE EXCEPTION 'Statement subject does not exist: %.%', NEW.subject_table, NEW.subject_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pul_004_guard_event_classification_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
	IF OLD.classification_run_id IS DISTINCT FROM NEW.classification_run_id THEN
		RAISE EXCEPTION 'Pulse event classification lineage is immutable';
	END IF;
	RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pul_004_guard_pipeline_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'Pulse pipeline runs are retained evidence and cannot be deleted';
	END IF;
	IF OLD.id IS DISTINCT FROM NEW.id
		OR OLD.stage IS DISTINCT FROM NEW.stage
		OR OLD.version_key IS DISTINCT FROM NEW.version_key
		OR OLD.versions IS DISTINCT FROM NEW.versions
		OR OLD.started_at IS DISTINCT FROM NEW.started_at THEN
		RAISE EXCEPTION 'Pulse pipeline version identity is immutable';
	END IF;
	IF OLD.status <> 'running' THEN
		RAISE EXCEPTION 'Completed, failed, and legacy Pulse pipeline runs are immutable';
	END IF;
	IF NEW.status NOT IN ('completed', 'partial', 'failed') OR NEW.completed_at IS NULL THEN
		RAISE EXCEPTION 'A running Pulse pipeline run may only close to a terminal status';
	END IF;
	RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pul_004_guard_raw_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
	IF OLD.ingest_run_id IS DISTINCT FROM NEW.ingest_run_id THEN
		RAISE EXCEPTION 'Raw-event ingest lineage is immutable';
	END IF;
	IF OLD.cluster_run_id IS NOT NULL AND OLD.cluster_run_id IS DISTINCT FROM NEW.cluster_run_id THEN
		RAISE EXCEPTION 'Raw-event cluster lineage is write-once';
	END IF;
	IF OLD.classification_run_id IS NOT NULL AND OLD.classification_run_id IS DISTINCT FROM NEW.classification_run_id THEN
		RAISE EXCEPTION 'Raw-event classification lineage is write-once';
	END IF;
	RETURN NEW;
END;
$function$
